  logic [LP_MAP_LAYERS-1:0] map_dropped;
  logic [LP_MAP_LAYERS-1:0] map_cfg_bad;
  logic [             15:0] map_level    [LP_MAP_LAYERS];
  logic [LP_MAP_LAYERS-1:0] map_err_layer_set;

  for (genvar gi = 0; gi < P_NUM_LAYERS; gi++) begin : g_layer_used
