    if (!rst_n) begin
      wr_addr_q    <= '0;
      wr_addr_held <= 1'b0;
    end else begin
      if (axil_awvalid && axil_awready) begin
        wr_addr_q    <= axil_awaddr;
        wr_addr_held <= 1'b1;
      end
      if (axil_bvalid && axil_bready) begin
        wr_addr_held <= 1'b0;
      end
    end
  end

